export const P2_FILES = Object.keys(CHANGES)
/** [text this change has, text the base has] per file, in the order they are put back (read-only: for the test that proves them). */
export const P2_PAIRS = CHANGES
export const P2_NEW_FILES = ["components/publish-p2.tsx","components/studio-viewer-theme-provider.tsx","lib/studio-p2-publish.ts"]

/** `text` of repo file `rel` without this change's additions (any other file comes back as it is). */
export function stripP2Publish(rel, text) {
  const changes = CHANGES[rel]
  return changes ? changes.reduce((out, [from, to]) => out.replace(from, () => to), text) : text
}
